  /// Update device credentials (updateDeviceCredentials)
  /// During device creation, platform generates random &#39;ACCESS_TOKEN&#39; credentials. Use this method to update the device credentials. First use &#39;getDeviceCredentialsByDeviceId&#39; to get the credentials id and value. Then use current method to update the credentials type and value. It is not possible to create multiple device credentials for the same device. The structure of device credentials id and value is simple for the &#39;ACCESS_TOKEN&#39; but is much more complex for the &#39;MQTT_BASIC&#39; or &#39;LWM2M_CREDENTIALS&#39;. You may find the example of device with different type of credentials below:   - Credentials type: **\&quot;Access token\&quot;** with **device ID** and with **device ID** below:   &#x60;&#x60;&#x60;json {   \&quot;id\&quot;: {     \&quot;id\&quot;:\&quot;c886a090-168d-11ee-87c9-6f157dbc816a\&quot;    },   \&quot;deviceId\&quot;: {     \&quot;id\&quot;:\&quot;c5fb3ac0-168d-11ee-87c9-6f157dbc816a\&quot;,     \&quot;entityType\&quot;:\&quot;DEVICE\&quot;    },   \&quot;credentialsType\&quot;: \&quot;ACCESS_TOKEN\&quot;,   \&quot;credentialsId\&quot;: \&quot;6hmxew8pmmzng4e3une4\&quot; } &#x60;&#x60;&#x60;  - Credentials type: **\&quot;X509\&quot;** with **device profile ID** below:   Note: **credentialsId** -  format **Sha3Hash**, **certificateValue** - format **PEM** (with \&quot;--BEGIN CERTIFICATE----\&quot; and  -\&quot;----END CERTIFICATE-\&quot;).  &#x60;&#x60;&#x60;json {   \&quot;id\&quot;: {     \&quot;id\&quot;:\&quot;309bd9c0-14f4-11ee-9fc9-d9b7463abb63\&quot;    },   \&quot;deviceId\&quot;: {     \&quot;id\&quot;:\&quot;3092b200-14f4-11ee-9fc9-d9b7463abb63\&quot;,     \&quot;entityType\&quot;:\&quot;DEVICE\&quot;    },   \&quot;credentialsType\&quot;: \&quot;X509_CERTIFICATE\&quot;,   \&quot;credentialsId\&quot;: \&quot;6b8adb49015500e51a527acd332b51684ab9b49b4ade03a9582a44c455e2e9b6\&quot;,   \&quot;credentialsValue\&quot;: \&quot;-----BEGIN CERTIFICATE----- &#x3D;&#x3D; -----END CERTIFICATE-----\&quot; } &#x60;&#x60;&#x60;  - Credentials type: **\&quot;MQTT_BASIC\&quot;** with **device profile ID** below:   &#x60;&#x60;&#x60;json {   \&quot;id\&quot;: {     \&quot;id\&quot;:\&quot;d877ffb0-14f5-11ee-9fc9-d9b7463abb63\&quot;    },   \&quot;deviceId\&quot;: {     \&quot;id\&quot;:\&quot;d875dcd0-14f5-11ee-9fc9-d9b7463abb63\&quot;,     \&quot;entityType\&quot;:\&quot;DEVICE\&quot;    },   \&quot;credentialsType\&quot;: \&quot;MQTT_BASIC\&quot;,   \&quot;credentialsValue\&quot;: \&quot;{\\\&quot;clientId\\\&quot;:\\\&quot;juy03yv4owqxcmqhqtvk\\\&quot;,\\\&quot;userName\\\&quot;:\\\&quot;ov19fxca0cyjn7lm7w7u\\\&quot;,\\\&quot;password\\\&quot;:\\\&quot;twy94he114dfi9usyk1o\\\&quot;}\&quot; } &#x60;&#x60;&#x60;  - You may find the example of **LwM2M** device and **RPK** credentials below:   Note: LwM2M device - only existing device profile ID (Transport configuration -&gt; Transport type: \&quot;LWM2M\&quot;.  &#x60;&#x60;&#x60;json {   \&quot;id\&quot;: {     \&quot;id\&quot;:\&quot;e238d4d0-1689-11ee-98c6-1713c1be5a8e\&quot;    },   \&quot;deviceId\&quot;: {     \&quot;id\&quot;:\&quot;e232e160-1689-11ee-98c6-1713c1be5a8e\&quot;,     \&quot;entityType\&quot;:\&quot;DEVICE\&quot;    },   \&quot;credentialsType\&quot;: \&quot;LWM2M_CREDENTIALS\&quot;,   \&quot;credentialsId\&quot;: \&quot;LwRpk00000000\&quot;,   \&quot;credentialsValue\&quot;:        \&quot;{\\\&quot;client\\\&quot;:{ \\\&quot;endpoint\\\&quot;:\\\&quot;LwRpk00000000\\\&quot;, \\\&quot;securityConfigClientMode\\\&quot;:\\\&quot;RPK\\\&quot;, \\\&quot;key\\\&quot;:\\\&quot;MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEdvBZZ2vQRK9wgDhctj6B1c7bxR3Z0wYg1+YdoYFnVUKWb+rIfTTyYK9tmQJx5Vlb5fxdLnVv1RJOPiwsLIQbAA&#x3D;&#x3D;\\\&quot;   }, \\\&quot;bootstrap\\\&quot;:{ \\\&quot;bootstrapServer\\\&quot;:{ \\\&quot;securityMode\\\&quot;:\\\&quot;RPK\\\&quot;, \\\&quot;clientPublicKeyOrId\\\&quot;:\\\&quot;MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEUEBxNl/RcYJNm8mk91CyVXoIJiROYDlXcSSqK6e5bDHwOW4ZiN2lNnXalyF0Jxw8MbAytnDMERXyAja5VEMeVQ&#x3D;&#x3D;\\\&quot;, \\\&quot;clientSecretKey\\\&quot;:\\\&quot;MIGHAgEAMBMGByqGSM49AgEGCCqGSM49AwEHBG0wawIBAQQgd9GAx7yZW37autew5KZykn4IgRpge/tZSjnudnZJnMahRANCAARQQHE2X9Fxgk2byaT3ULJVeggmJE5gOVdxJKorp7lsMfA5bhmI3aU2ddqXIXQnHDwxsDK2cMwRFfICNrlUQx5V\\\&quot;}, \\\&quot;lwm2mServer\\\&quot;:{ \\\&quot;securityMode\\\&quot;:\\\&quot;RPK\\\&quot;, \\\&quot;clientPublicKeyOrId\\\&quot;:\\\&quot;MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEUEBxNl/RcYJNm8mk91CyVXoIJiROYDlXcSSqK6e5bDHwOW4ZiN2lNnXalyF0Jxw8MbAytnDMERXyAja5VEMeVQ&#x3D;&#x3D;\\\&quot;, \\\&quot;clientSecretKey\\\&quot;:\\\&quot;MIGHAgEAMBMGByqGSM49AgEGCCqGSM49AwEHBG0wawIBAQQgd9GAx7yZW37autew5KZykn4IgRpge/tZSjnudnZJnMahRANCAARQQHE2X9Fxgk2byaT3ULJVeggmJE5gOVdxJKorp7lsMfA5bhmI3aU2ddqXIXQnHDwxsDK2cMwRFfICNrlUQx5V\\\&quot;}} }\&quot; } &#x60;&#x60;&#x60;  Update to real value:  - &#39;id&#39; (this is id of Device Credentials -&gt;  \&quot;Get Device Credentials (getDeviceCredentialsByDeviceId)\&quot;,  - &#39;deviceId.id&#39; (this is id of Device). Remove &#39;tenantId&#39; and optionally &#39;customerId&#39; from the request body example (below) to create new Device entity.  Available for users with &#39;TENANT_ADMIN&#39; authority.
  ///
  /// Parameters:
  /// * [deviceCredentials]
  /// * [cancelToken] - A [CancelToken] that can be used to cancel the operation
  /// * [headers] - Can be used to add additional headers to the request
  /// * [extras] - Can be used to add flags to the request
  /// * [validateStatus] - A [ValidateStatus] callback that can be used to determine request success based on the HTTP status of the response
  /// * [onSendProgress] - A [ProgressCallback] that can be used to get the send progress
  /// * [onReceiveProgress] - A [ProgressCallback] that can be used to get the receive progress
  ///
  /// Returns a [Future] containing a [Response] with a [DeviceCredentials] as data
  /// Throws [DioException] if API call or serialization fails
  Future<Response<DeviceCredentials>> updateDeviceCredentials({
    required DeviceCredentials deviceCredentials,
    CancelToken? cancelToken,
    Map<String, dynamic>? headers,
    Map<String, dynamic>? extra,
    ValidateStatus? validateStatus,
    ProgressCallback? onSendProgress,
    ProgressCallback? onReceiveProgress,
  }) async {
    final _serializers =
        this._serializers ?? apiSerializers(registerDeviceCredentials);
    final _path = r'/api/device/credentials';
    final _options = Options(
      method: r'POST',
      headers: <String, dynamic>{...?headers},
      extra: <String, dynamic>{
        'secure': <Map<String, String>>[
          {
            'type': 'apiKey',
            'name': 'ApiKeyForm',
            'keyName': 'X-Authorization',
            'where': 'header',
          },
          {'type': 'http', 'scheme': 'loginPassword', 'name': 'HttpLoginForm'},
        ],
        ...?extra,
      },
      contentType: 'application/json',
      validateStatus: validateStatus,
    );

    dynamic _bodyData;

    try {
      const _type = FullType(DeviceCredentials);
      _bodyData = _serializers.serialize(
        deviceCredentials,
        specifiedType: _type,
      );
    } catch (error, stackTrace) {
      throw DioException(
        requestOptions: _options.compose(_dio.options, _path),
        type: DioExceptionType.unknown,
        error: error,
        stackTrace: stackTrace,
      );
    }

    final _response = await _dio.request<Object>(
      _path,
      data: _bodyData,
      options: _options,
      cancelToken: cancelToken,
      onSendProgress: onSendProgress,
      onReceiveProgress: onReceiveProgress,
    );

    DeviceCredentials? _responseData;

    try {
      final rawResponse = _response.data;
      _responseData = rawResponse == null
          ? null
          : _serializers.deserialize(
                  rawResponse,
                  specifiedType: const FullType(DeviceCredentials),
                )
                as DeviceCredentials;
    } catch (error, stackTrace) {
      throw DioException(
        requestOptions: _response.requestOptions,
        response: _response,
        type: DioExceptionType.unknown,
        error: error,
        stackTrace: stackTrace,
      );
    }

    return Response<DeviceCredentials>(
      data: _responseData,
      headers: _response.headers,
      isRedirect: _response.isRedirect,
      requestOptions: _response.requestOptions,
      redirects: _response.redirects,
      statusCode: _response.statusCode,
      statusMessage: _response.statusMessage,
      extra: _response.extra,
